INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(4001, 'Numbers 20:20', 'Numbers', 20, 20, '&nbsp;خو ادوميانو بيا ووئيل، ”تاسو مۀ تېرېږئ.“ او هغوئ د يو طاقتور لښکر سره په بنى اِسرائيلو باندې حملې دپاره راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4002, 'Numbers 20:21', 'Numbers', 20, 21, '&nbsp;ځکه چې ادوميانو بنى اِسرائيل په خپله علاقه کښې تېرېدو ته نۀ پرېښودل، نو بنى اِسرائيل په بله لار لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4003, 'Numbers 20:22', 'Numbers', 20, 22, '&nbsp;د بنى اِسرائيلو ټول قوم د قادِس نه لاړل او د حُور غرۀ ته ورسېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4004, 'Numbers 20:23', 'Numbers', 20, 23, '&nbsp;چې د ادوم په سرحد باندې دے. هلته مالِک خُدائ موسىٰ او هارون ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4005, 'Numbers 20:24', 'Numbers', 20, 24, '&nbsp;”هارون به هغه مُلک ته ورننه نۀ وځى د کوم چې ما بنى اِسرائيلو له د ورکولو وعده کړې ده، هغه به مړ شى، ځکه چې په مريبه کښې تاسو زما د حُکم نه بغاوت کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4006, 'Numbers 20:25', 'Numbers', 20, 25, '&nbsp;هارون او د هغۀ زوئ اِلى‌عزر بره د حُور غرۀ ته بوځه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4007, 'Numbers 20:26', 'Numbers', 20, 26, '&nbsp;او هلته د هارون نه د اِمامانو لِباس وباسه او اِلى‌عزر ته يې ورواچوه. هارون به هلته مړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4008, 'Numbers 20:27', 'Numbers', 20, 27, '&nbsp;موسىٰ هم هغه شان وکړل چې څنګه مالِک خُدائ حُکم ورکړے وو. هغوئ د ټول قوم په مخکښې د حُور غرۀ ته وختل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4009, 'Numbers 20:28', 'Numbers', 20, 28, '&nbsp;او موسىٰ د هارون نه د اِمامانو لِباس وويستلو او اِلى‌عزر ته يې ورواغوستلو. هارون هلته د غرۀ په سر باندې مړ شو او موسىٰ او اِلى‌عزر د غرۀ نه راکوز شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4010, 'Numbers 20:29', 'Numbers', 20, 29, '&nbsp;د اِسرائيلو ټول قوم ته پته ولګېده چې هارون مړ دے او دېرش ورځې هغوئ د هغۀ په غم غمژن وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4011, 'Numbers 21:1', 'Numbers', 21, 1, '&nbsp;کله چې د کنعان په جنوبى حِصه کښې د عراد بادشاه واورېدل چې بنى اِسرائيل د اتهارِم په لاره راروان دى، نو هغۀ ورباندې حمله وکړه او څۀ يې ترې نه ونيول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4012, 'Numbers 21:2', 'Numbers', 21, 2, '&nbsp;بيا بنى اِسرائيلو د مالِک خُدائ سره دا وعده وکړه، ”کۀ تۀ مونږ په دې خلقو بريالى کړې، نو مونږ به د هغوئ ښارونه پوره تباه کړُو او تا ته به وقف شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4013, 'Numbers 21:3', 'Numbers', 21, 3, '&nbsp;مالِک خُدائ د هغوئ آواز واورېدو او په کنعانيانو يې بريالى کړل. نو بنى اِسرائيلو هغوئ او د هغوئ ښارونه تباه کړل او په هغه ځائ يې حُرمه نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4014, 'Numbers 21:4', 'Numbers', 21, 4, '&nbsp;بنى اِسرائيليان د حُور غرۀ نه د بحرِقُلزم په لار روان شول چې د ادوم نه ګېرچاپېره مزل وکړى. خو په لاره کښې خلق ډېر بې‌صبره شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4015, 'Numbers 21:5', 'Numbers', 21, 5, '&nbsp;او د خُدائ پاک او موسىٰ خِلاف يې خبرې شروع کړې. هغوئ ووئيل، ”تاسو مونږ ولې د مِصر نه راوويستلو د دې دپاره څۀ چې په دې صحرا کښې مړۀ شُو، چرته چې نۀ روټۍ شته او نۀ اوبۀ شته؟ نور مونږ دا بې‌کاره خوراک نۀ شُو برداشت کولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4016, 'Numbers 21:6', 'Numbers', 21, 6, '&nbsp;بيا مالِک خُدائ په خلقو باندې زهريله ماران راولېږل او ډېر اِسرائيليان يې وچيچل او مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4017, 'Numbers 21:7', 'Numbers', 21, 7, '&nbsp;خلق موسىٰ له راغلل او ورته يې ووئيل، ”مونږ دا ګناه کړې ده چې د مالِک خُدائ او ستا خِلاف مو خبرې کړې دى. نو مالِک خُدائ ته سوال وکړه چې دا ماران لرې کړى.“ نو موسىٰ د خلقو دپاره دُعا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4018, 'Numbers 21:8', 'Numbers', 21, 8, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل چې د يو زهريله مار نمونه جوړه کړه او په يوه ډاګه يې ولګوه، نو هر څوک چې چيچلے شوے وى او هغې ته وګورى نو روغ به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4019, 'Numbers 21:9', 'Numbers', 21, 9, '&nbsp;نو موسىٰ د پيتلو نه مار جوړ کړو او په يوه ډاګه باندې يې ولګولو. هر څوک به چې چيچلے شوے وو او هغۀ به د پيتلو مار ته وکتل نو ژوندے به پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4020, 'Numbers 21:10', 'Numbers', 21, 10, '&nbsp;اِسرائيليان وړاندې لاړل او په اوبوت کښې يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4021, 'Numbers 21:11', 'Numbers', 21, 11, '&nbsp;چې د هغه ځائ نه لاړل نو د موآبيانو د علاقې نمرخاتۀ طرف ته د عى عباريم په صحرا کښې يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4022, 'Numbers 21:12', 'Numbers', 21, 12, '&nbsp;بيا هغوئ د زرد په وادۍ کښې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4023, 'Numbers 21:13', 'Numbers', 21, 13, '&nbsp;هغوئ د هغه ځائ نه بيا لاړل او د ارنون د سيند نه پورىې غاړه يې خېمې ولګولې په هغه صحرا کښې چې د اموريانو د علاقې پورې خوره وه. ارنون د موآبيانو او اموريانو په مينځ کښې د حد پوله وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4024, 'Numbers 21:14', 'Numbers', 21, 14, '&nbsp;نو دا ځکه د مالِک خُدائ د جنګونو په کِتاب کښې ليکلى دى، ”د سوفه په علاقه کښې د واهيب ښار او هغه واديانې، د ارنون سيند،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4025, 'Numbers 21:15', 'Numbers', 21, 15, '&nbsp;د واديانو ژور ځايونه چې د عار ښار پورې خوارۀ دى او چې د موآب د حد پولې ته رسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4026, 'Numbers 21:16', 'Numbers', 21, 16, '&nbsp;د هغې ځائ نه هغوئ هغه کوهى له لاړل چې د بير په نامه ياديږى، دا هغه کوهے دے چې مالِک خُدائ موسىٰ ته وفرمائيل، ”خلق راغونډ کړه او زۀ به هغوئ له اوبۀ ورکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4027, 'Numbers 21:17', 'Numbers', 21, 17, '&nbsp;په هغه وخت بنى اِسرائيلو دا سندره ووئيله، ”کُوهو، خپلې اوبۀ راوباسئ، مونږ ورته يوه سندره وايو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4028, 'Numbers 21:18', 'Numbers', 21, 18, '&nbsp;کوهے شهزادګانو کنستلے دے او د خلقو د مشرانو سره د بادشاهۍ د امسا سره او د هغوئ د امساګانو سره.“ هغوئ د صحرا نه متنه ته لاړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4029, 'Numbers 21:19', 'Numbers', 21, 19, '&nbsp;او د هغې ځائ نه نحلى‌اېل ته او د نحلى‌اېل نه بامات ته لاړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4030, 'Numbers 21:20', 'Numbers', 21, 20, '&nbsp;او د بامات نه د موآبيانو په علاقه کښې وادۍ ته لاړل، د پِسګه د غرۀ د سر نه لاندې، چې مخ يې صحرا ته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4031, 'Numbers 21:21', 'Numbers', 21, 21, '&nbsp;بيا بنى اِسرائيلو د اموريانو بادشاه سيحون ته پېغام وړُونکى ولېږل چې ورته ووائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4032, 'Numbers 21:22', 'Numbers', 21, 22, '&nbsp;”مونږ پرېږده چې ستا په مُلک کښې تېر شُو. او مونږ او زمونږ څاروى به د لارې نه نۀ اوړُو او نۀ به ستاسو پټو او د انګورو باغونو ته ځُو او مونږ به ستاسو د کُوهو نه اوبۀ نۀ څښو، په لويه لاره به سيدها روان يُو چې ستاسو علاقې نه ووځُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4033, 'Numbers 21:23', 'Numbers', 21, 23, '&nbsp;خو سيحون بنى اِسرائيلو له اجازت نۀ ورکولو چې د هغۀ د علاقې نه تېر شى. هغۀ خپل ټول لښکر راجمع کړو او په صحرا کښې يهض ته ووتل او په بنى اِسرائيلو يې حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4034, 'Numbers 21:24', 'Numbers', 21, 24, '&nbsp;خو بنى اِسرائيلو په جنګ کښې ډېر دشمنان ووژل او د ارنون سيند نه واخله تر يبوق سيند پورې زمکه يې ترې نه ونيوله، خو د يبوق نه وروستو د عمونيانو د علاقې د حد پوله ډېره مضبوطه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4035, 'Numbers 21:25', 'Numbers', 21, 25, '&nbsp;نو بنى اِسرائيلو د اموريانو ټول ښارونه چې په هغوئ کښې حسبون او ګېرچاپېره کلى هم شامل وو ونيول او بيا هغوئ هلته اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4036, 'Numbers 21:26', 'Numbers', 21, 26, '&nbsp;حسبون د اموريانو د بادشاه سيحون مرکزى ښار وو، سيحون د موآب پخوانى بادشاه خِلاف جنګ کړے وو او د ارنون سيند پورې د هغۀ ټوله زمکه يې نيولې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4037, 'Numbers 21:27', 'Numbers', 21, 27, '&nbsp;نو دا ځکه شاعران وائى، ”د سيحون بادشاه ښار ته، حسبون ته راشه، مونږ دا آباد او ودان غواړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4038, 'Numbers 21:28', 'Numbers', 21, 28, '&nbsp;يوه ورځ د دې ښار حسبون نه د سيحون لښکر د اور په شان لاړو، هغوئ په موآب کښې د عار ښار وران کړو او د پاسنى ارنون غرونه يې دړې وړې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4039, 'Numbers 21:29', 'Numbers', 21, 29, '&nbsp;د موآب خلقو ستاسو دپاره دا څومره خرابه خبره ده. د کموس عبادت کوونکو تاسو تباهۍ له راوستلے شوى يئ. ستاسو خُدائ خلق مهاجر جوړ کړى دى او ستاسو ښځې د اموريانو د بادشاه قېديانې شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4040, 'Numbers 21:30', 'Numbers', 21, 30, '&nbsp;خو د هغوئ اولاد تباه شوے دے، د حسبون نه واخله تر ديبون پورې، د نشيم نه واخله تر نفح پورې، چې ميدبا ته نزدې دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4041, 'Numbers 21:31', 'Numbers', 21, 31, '&nbsp;نو اِسرائيليان د اموريانو په علاقه کښې دېره شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4042, 'Numbers 21:32', 'Numbers', 21, 32, '&nbsp;او موسىٰ کسان ولېږل چې په يعزير ښار باندې حمله کولو دپاره ښۀ لاره معلومه کړى. بنى اِسرائيلو دا او ګېرچاپېره ښارونه ونيول او چې کوم اموريان هلته اوسېدل هغه يې وشړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4043, 'Numbers 21:33', 'Numbers', 21, 33, '&nbsp;بنى اِسرائيل راوګرځېدل او د بسن په لاره لاړل او د بسن بادشاه عوج د خپل لښکر سره راووتلو چې په ادرعى کښې په هغوئ باندې حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4044, 'Numbers 21:34', 'Numbers', 21, 34, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”د هغۀ نه مۀ يرېږه. زۀ به تا په هغۀ باندې، د هغۀ په ټولو خلقو او د هغۀ په مُلک باندې بريالے کړم. د هغۀ سره هم هغه شان کار وکړه لکه څنګه چې دې سيحون سره کړے وو، سيحون چې په حسبون کښې د اموريانو بادشاه وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4045, 'Numbers 21:35', 'Numbers', 21, 35, '&nbsp;نو بنى اِسرائيلو عوج، د هغۀ زامن او د هغۀ ټول خلق ووژل، هيڅ څوک يې ژوندى پرې نۀ ښودل او بيا هغوئ د هغۀ مُلک ونيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4046, 'Numbers 22:1', 'Numbers', 22, 1, '&nbsp;بنى اِسرائيلو مخکښې سفر کولو او د موآب په مېدانونو کښې يې د اُردن پورې غاړه يريحو ته مخامخ خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4047, 'Numbers 22:2', 'Numbers', 22, 2, '&nbsp;کله چې د موآب بادشاه د صفور زوئ بلق خبر شو چې بنى اِسرائيلو په اموريانو باندې څۀ کړى وُو او بنى اِسرائيل څومره بې‌شمېره وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4048, 'Numbers 22:3', 'Numbers', 22, 3, '&nbsp;نو په هغۀ او د هغۀ په ټولو خلقو د يرې نه وېښتۀ نېغ ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4049, 'Numbers 22:4', 'Numbers', 22, 4, '&nbsp;موآبيانو د ميديانيانو مشرانو ته ووئيل، ”زر به دا لښکر زمونږ ګېرچاپېره هر څۀ تباه کړى، لکه چې يو آزاد غوَيے په ګياه ورګډ شى.“ نو بلق بادشاه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4050, 'Numbers 22:5', 'Numbers', 22, 5, '&nbsp;پېغام وړُونکى ولېږل چې د بعور زوئ بلعام راوغواړى، چې هغه د فرات د سيند سره نزدې په پتور کښې وو. هغوئ هغۀ له د بلق نه دا پېغام راوړو، ”زۀ غواړم چې تۀ خبر شې چې د مِصر نه يو لوئ قوم راغلے دے، هغوئ د زمکې مخ پټ کړے دے او وائى چې زمونږ مُلک قبضه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4051, 'Numbers 22:6', 'Numbers', 22, 6, '&nbsp;هغوئ زمونږ نه طاقتور دى، نو زۀ درته مِنت کوم چې زما دپاره په هغوئ لعنت ووايه. نو کېدے شى چې هغوئ له شکست ورکړو او د مُلک نه يې وشړُو. ما ته پته ده چې تاسو د چا دپاره برکت غواړئ نو هغه برکت مومى او چې په چا لعنت ووايئ نو هغه لعنتى شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4052, 'Numbers 22:7', 'Numbers', 22, 7, '&nbsp;نو د موآبيانو او ميديانيانو مشرانو د لعنت غوښتلو قيمت واخستلو او بلعام له لاړل او د بلق پېغام يې ورته واورولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4053, 'Numbers 22:8', 'Numbers', 22, 8, '&nbsp;بلعام هغوئ ته ووئيل، ”تاسو نن شپه دلته تېره کړئ او چې مالِک خُدائ ما ته څۀ هم ووائى نو هغه به سبا زۀ تاسو ته ووايم.“ نو د موآبيانو مشران د بلعام سره ايسار شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4054, 'Numbers 22:9', 'Numbers', 22, 9, '&nbsp;خُدائ پاک بلعام ته څرګند شو او ورته يې وفرمائيل، ”دا تا سره خلق څوک دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4055, 'Numbers 22:10', 'Numbers', 22, 10, '&nbsp;هغۀ خُدائ پاک ته وفرمائيل، ”د موآب بادشاه بلق هغوئ ما له رالېږلى دى، هغوئ وائى چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4056, 'Numbers 22:11', 'Numbers', 22, 11, '&nbsp;کوم خلق چې د مِصر نه راغلى دى هغوئ د ټولې زمکې مخ پټ کړے دے. هغه ما ته وائى چې د هغۀ دپاره په هغوئ لعنت ووايم، نو هغه به شکست ورکړى او وبه يې شړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4057, 'Numbers 22:12', 'Numbers', 22, 12, '&nbsp;خُدائ پاک بلعام ته وفرمائيل، ”تۀ د هغوئ سره مۀ ځه او بنى اِسرائيلو دپاره لعنت مۀ غواړه، ځکه چې ما هغوئ له برکت ورکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4058, 'Numbers 22:13', 'Numbers', 22, 13, '&nbsp;په ورپسې سحر بلعام د بلق پېغام وړونکو له ورَغلو او ورته يې ووئيل، ”واپس خپل مُلک ته لاړ شئ، مالِک خُدائ زۀ تاسو سره تلو نه منع کړے يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4059, 'Numbers 22:14', 'Numbers', 22, 14, '&nbsp;نو د موآب مشران واپس بلق له لاړل او هغۀ ته يې ووئيل چې بلعام د هغوئ سره د راتلو نه اِنکار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4060, 'Numbers 22:15', 'Numbers', 22, 15, '&nbsp;نو بلق نور مشران ورولېږل، چې هغوئ د مخکښېنو نه زيات او ډېر عزتمند وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4061, 'Numbers 22:16', 'Numbers', 22, 16, '&nbsp;هغوئ بلعام له ورغلل او د بلق دا پېغام يې ورته واورولو، ”زۀ ستا مِنت کوم چې تۀ به خامخا ما له راځې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4062, 'Numbers 22:17', 'Numbers', 22, 17, '&nbsp;زۀ به تا له لوئ اِنعام درکړم او چې تۀ څۀ هم وائې نو زۀ به يې کوم. خو لږ راشه او په دې خلقو زما د خاطره لعنت ووايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4063, 'Numbers 22:18', 'Numbers', 22, 18, '&nbsp;خو بلعام جواب ورکړو، ”کۀ بلق د خپل محل ټول سپين زر او سرۀ زر هم ما له راکړى، نو زۀ به د خپل مالِک خُدائ د يوې وړې نه وړې خبرې نافرمانى هم ونۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4064, 'Numbers 22:19', 'Numbers', 22, 19, '&nbsp;خو نن تاسو مونږ سره شپه وکړئ، نو زۀ به پته ولګوم چې مالِک خُدائ ما ته نور څۀ فرمائيل غواړى او کۀ نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4065, 'Numbers 22:20', 'Numbers', 22, 20, '&nbsp;په هغه شپه خُدائ پاک بلعام ته څرګند شو او ورته يې وفرمائيل، ”کۀ چرې دا سړى تا له راغلل او درته يې ووئيل چې مونږ سره لاړ شه، نو بيا ځان تيار کړه او ورسره لاړ شه، خو هغه څۀ کوه چې څۀ درته زۀ وايم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4066, 'Numbers 22:21', 'Numbers', 22, 21, '&nbsp;نو په بل سحر بلعام خپله خره کته کړه او د موآبيانو د مشرانو سره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4067, 'Numbers 22:22', 'Numbers', 22, 22, '&nbsp;خُدائ پاک د بلعام په تلو غصه وو. بلعام په خپله خره سور وو او ور سره دوه خِدمتګاران روان وُو، نو د مالِک خُدائ فرښته ورته په لاره کښې ودرېدله چې هغه ودروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4068, 'Numbers 22:23', 'Numbers', 22, 23, '&nbsp;کله چې خرې د مالِک خُدائ فرښته وليده چې په لاره کښې ولاړه وه او په لاس کښې يې تُوره نيولې وه، نو خرې لاره پرېښودله او پټو ته لاړه. بلعام خره ووهله او واپس يې لارې ته راوستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4069, 'Numbers 22:24', 'Numbers', 22, 24, '&nbsp;بيا د مالِک خُدائ فرښته ورته هلته ودرېدله چرته چې د دوو انګورو باغونو په مينځ کښې لار تنګه وه او دواړو طرفونو ته يې د کاڼو دېوال وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4070, 'Numbers 22:25', 'Numbers', 22, 25, '&nbsp;کله چې خرې د مالِک خُدائ فرښته وليده، نو خره دېوال ته ښۀ ورنزدې شوه او د بلعام پښه يې د دېوال سره راښکله. بلعام بيا خره ووهله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4071, 'Numbers 22:26', 'Numbers', 22, 26, '&nbsp;د مالِک خُدائ فرښته يو ځل بيا مخکښې لاړه، په داسې يو تنګ ځائ کښې ودرېدله چرته چې لاره دومره تنګه وه چې د اخوا ديخوا کېدو ځائ نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4072, 'Numbers 22:27', 'Numbers', 22, 27, '&nbsp;دا ځل، چې کله خرې فرښته وليده، نو هغه څملاسته. بلعام غصه شو او د امسا سره د خرې په وهلو يې شروع وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4073, 'Numbers 22:28', 'Numbers', 22, 28, '&nbsp;بيا مالِک خُدائ خرې له د خبرو کولو طاقت ورکړو او خرې بلعام ته ووئيل، ”ما تا سره څۀ بد کړى دى؟ تا زۀ دا درې ځلې ولې ووهلم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4074, 'Numbers 22:29', 'Numbers', 22, 29, '&nbsp;بلعام ورته ووئيل، ”ځکه چې تا زما نه کم عقل جوړ کړے دے. کۀ زما سره تُوره وے، نو ما به تۀ وژلې وې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4075, 'Numbers 22:30', 'Numbers', 22, 30, '&nbsp;خرې ورته ووئيل، ”ولې زۀ څۀ هغه خره نۀ يم چې په کومه باندې تا ټول عُمر سورلى کړې ده؟ مخکښې ما کله تا سره داسې کار کړے دے؟“ نو هغۀ ورته ووئيل، ”نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4076, 'Numbers 22:31', 'Numbers', 22, 31, '&nbsp;بيا مالِک خُدائ بلعام ته فرښته څرګنده کړه چې هلته د خپلې تُورې سره ولاړه وه، او بلعام ټيټ شو او سر يې په زمکه ولګولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4077, 'Numbers 22:32', 'Numbers', 22, 32, '&nbsp;د مالِک خُدائ فرښتې هغۀ ته وفرمائيل، ”تا دا درې ځلې خپله خره ولې ووهله؟ زۀ ستا د ودرولو دپاره راغلې يم، ځکه چې تۀ څۀ کوې هغه زما خِلاف دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4078, 'Numbers 22:33', 'Numbers', 22, 33, '&nbsp;خو ستا خرې زۀ وليدم او زما نه درې ځلې واوړېدله. کۀ هغه ګرځېدلے نۀ وے، نو ما به تۀ وژلے وے او هغه خره به مې ژوندۍ پرېښې وه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4079, 'Numbers 22:34', 'Numbers', 22, 34, '&nbsp;بلعام د مالِک خُدائ فرښتې ته ووئيل، ”ما ګناه کړې ده. ما ته پته نۀ وه چې تۀ زما د ايسارولو دپاره په لاره کښې ولاړه يې، خو کۀ ستا خوښه نۀ وى نو زۀ به نۀ ځم او واپس به خپل کور ته لاړ شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4080, 'Numbers 22:35', 'Numbers', 22, 35, '&nbsp;خو فرښتې ورته وفرمائيل، ”د دې سړو سره لاړ شه، خو صِرف هغه څۀ وايه څۀ چې زۀ درته وايم.“ نو بلعام د بلق د مشرانو سره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4081, 'Numbers 22:36', 'Numbers', 22, 36, '&nbsp;کله چې بلق خبر شو چې بلعام راروان دے، نو هغه ورَغلو چې په عار کښې ورسره مِلاو شى، دا ښار د ارنون د سيند سره د موآب په سرحد باندې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4082, 'Numbers 22:37', 'Numbers', 22, 37, '&nbsp;بلق هغۀ ته ووئيل، ”ما چې په وړومبى ځل تۀ راوغوښتلې نو ولې رانۀ غلې؟ ستا خيال دا وو څۀ چې زۀ تا له اِنعام نۀ شم درکولے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4083, 'Numbers 22:38', 'Numbers', 22, 38, '&nbsp;بلعام ورته وفرمائيل، ”ولې زۀ تا له رانۀ غلم؟ زۀ چې څۀ وئيل غواړم نو د هغې اختيار نۀ لرم. زۀ به صِرف هغه وايم چې څۀ خُدائ پاک ما ته فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4084, 'Numbers 22:39', 'Numbers', 22, 39, '&nbsp;نو بلعام د بلق سره قِريَت‌حُصات ته لاړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4085, 'Numbers 22:40', 'Numbers', 22, 40, '&nbsp;چرته چې بلق څاروى او ګډې حلال کړل او څۀ غوښه يې بلعام او هغه مشرانو له ورکړه چې د هغۀ سره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4086, 'Numbers 22:41', 'Numbers', 22, 41, '&nbsp;په ورپسې سحر بلق بلعام بره باموت‌بعل ته بوتلو او هلته نه ورته څۀ اِسرائيليان ښکاره شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4087, 'Numbers 23:1', 'Numbers', 23, 1, '&nbsp;بلعام بلق ته ووئيل، ”دلته زما دپاره اووۀ قربان‌ګاه جوړې کړه او ما له اووۀ غوَيى او اووۀ ګډان راوله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4088, 'Numbers 23:2', 'Numbers', 23, 2, '&nbsp;بلق هم هغه شان وکړل چې څنګه بلعام وئيلى وُو، هغۀ او بلعام يو غوَيے او يو ګډ په هره يو قربان‌ګاه باندې پېش کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4089, 'Numbers 23:3', 'Numbers', 23, 3, '&nbsp;بيا بلعام بلق ته ووئيل، ”دلته د خپلې سوزېدونکې نذرانې سره ايسار شه نو زۀ ځم چې وګورم چې مالِک خُدائ ما ته راڅرګنديږى او کۀ نه. چې هغه ما ته څۀ هم ووائى نو زۀ به تا ته ووايم.“ نو هغه يو خوشى غر ته لاړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4090, 'Numbers 23:4', 'Numbers', 23, 4, '&nbsp;او خُدائ پاک هغۀ ته راڅرګند شو. بلعام ورته وفرمائيل، ”ما اووۀ قربان‌ګاه جوړې کړې دى او يو غوَيے او يو ګډ مې په هره يوه باندې پېش کړل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4091, 'Numbers 23:5', 'Numbers', 23, 5, '&nbsp;مالِک خُدائ بلعام ته د وئيلو دپاره خبرې وښودلې او واپس يې بلق له ولېږلو چې هغۀ ته د هغۀ پېغام ورسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4092, 'Numbers 23:6', 'Numbers', 23, 6, '&nbsp;نو هغه واپس لاړو او وې ليدل چې بلق د خپلې سوزېدونکې نذرانې سره ولاړ وو او د موآب ټول مشران ورسره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4093, 'Numbers 23:7', 'Numbers', 23, 7, '&nbsp;بلعام دا پېغام ورکړو، ”د موآب بادشاه بلق زۀ راوستلے يم د آرام نه، د نمرخاتۀ غرونو نه. هغۀ ووئيل چې، راشه او زما دپاره ووايه. په بنى اِسرائيلو باندې لعنت ووايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4094, 'Numbers 23:8', 'Numbers', 23, 8, '&nbsp;زۀ پرې څنګه لعنت وايم چې هغوئ خُدائ پاک نۀ وى لعنتى کړى، چې مالِک خُدائ په څۀ اِلزام نۀ وى لګولے نو زۀ پرې څنګه اِلزام ولګوم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4095, 'Numbers 23:9', 'Numbers', 23, 9, '&nbsp;د لوړو کاڼو نه زۀ هغوئ ګورم، د غرونو نه زۀ هغوئ وينم. هغوئ هغه خلق دى چې يواځې ژوند تېروى، هغوئ ته پته ده چې دوئ د نورو قومونو نه بختور دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4096, 'Numbers 23:10', 'Numbers', 23, 10, '&nbsp;د يعقوب اولاد د شګو په شان دے، څوک داسې شته چې شګې وشمېرى؟ پرېږده چې زۀ مړ شم د خُدائ پاک د خلقو په شان، پرېږده چې د صادقانو په شان په آرام مړ شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4097, 'Numbers 23:11', 'Numbers', 23, 11, '&nbsp;بيا بلق بلعام ته ووئيل، ”دا تا څۀ وکړل؟ ما تۀ د دې دپاره راوستلے يې چې زما په دشمنانو لعنت ووائې، خو تا د هغوئ دپاره صِرف برکت غوښتلے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4098, 'Numbers 23:12', 'Numbers', 23, 12, '&nbsp;هغۀ جواب ورکړو، ”زۀ به صِرف هغه څۀ وايم څۀ چې مالِک خُدائ ما ته وائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4099, 'Numbers 23:13', 'Numbers', 23, 13, '&nbsp;بيا بلق بلعام ته ووئيل، ”ما سره يو بل ځائ ته لاړ شه چې د هغه ځائ نه صرف لږ شان اِسرائيليان ښکارى. او د هغه ځائ نه تۀ په هغوئ لعنت ووايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4100, 'Numbers 23:14', 'Numbers', 23, 14, '&nbsp;بلق، بلعام د پِسګه د غرۀ په سر د ضُوفيم پټى ته بوتلو. هغۀ هلته هم اووۀ قربان‌ګاه جوړې کړې او يو غوَيے او يو ګډ يې په هره يوه باندې پېش کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');